const std=@import("std");
export fn tsvc_s351_direct_unrolled_saxpy(xo:?[*]const f64,l:usize,yo:?[*]f64,cap:usize)i64{if(xo==null or l<12 or l>82)return -1;const x=xo.?;const rd=x[0];if(!std.math.isFinite(rd) or @trunc(rd)!=rd or rd<5 or rd>40)return -1;const n:usize=@intFromFloat(rd);if(n%5!=0 or l!=2+2*n)return -1;for(1..l)|i|{if(!std.math.isFinite(x[i]) or @trunc(x[i])!=x[i] or @abs(x[i])>1)return -1;}if(yo==null or cap<n)return -2;const y=yo.?;var a:[40]f64=undefined;for(0..n)|i|{a[i]=x[2+i];}const alpha=x[1];var base:usize=0;while(base<n):(base+=5){const p0=alpha*x[2+n+base];a[base]=a[base]+p0;const p1=alpha*x[2+n+base+1];a[base+1]=a[base+1]+p1;const p2=alpha*x[2+n+base+2];a[base+2]=a[base+2]+p2;const p3=alpha*x[2+n+base+3];a[base+3]=a[base+3]+p3;const p4=alpha*x[2+n+base+4];a[base+4]=a[base+4]+p4;}for(0..n)|i|{y[i]=a[i];}return @intCast(n);}
